style.css:
/* Lomo Dreamscape — All Websites */
/* i really want this to be global */

:root {
  /* swap these colors to customize your film mood */
  --my-cream: #f3ead8;
  --my-paper: #e8dcc5;
  --my-burgundy: #985b54;
  --my-olive: #85866a;
  --my-ink: #493e35;
  --my-muted: #9d8977;
}

/* warm vintage page */
body {
  background-color: var(--my-cream) !important;
  color: var(--my-ink) !important;
  font-family: Georgia, "Times New Roman", serif !important;
}

/* nostalgic headings */
h1, h2, h3, h4 {
  color: var(--my-burgundy) !important;
  letter-spacing: 0.4px !important;
  font-weight: 500 !important;
}

/* soft film-inspired links */
a {
  color: var(--my-burgundy) !important;
  text-decoration-color: var(--my-olive) !important;
}

/* vintage paper surfaces */
article, section, main, aside {
  border-color: rgba(133, 112, 85, 0.2) !important;
}

/* analog photo frames */
img {
  border-radius: 3px !important;
  border: 5px solid #fffaf0 !important;
  box-shadow: 2px 4px 12px rgba(73, 62, 53, 0.15) !important;
}

/* softer buttons */
button, input, textarea, select {
  border-radius: 5px !important;
  border-color: var(--my-muted) !important;
}

/* gentle vintage selection */
::selection {
  background: var(--my-burgundy) !important;
  color: #fffaf0 !important;
}
